import { Component, signal } from '@angular/core';
import { FormField, email, form, required } from '@angular/forms/signals';

import { WrButton } from 'ngwr/button';
import { WrCard } from 'ngwr/card';
import { WrFormField } from 'ngwr/form';
import { WrInput } from 'ngwr/input';

@Component({
  selector: 'app-sign-in',
  templateUrl: './sign-in.html',
  // `FormField` is what makes `[formField]` a binding rather than an unknown
  // attribute — it is Angular's directive, not one of ngwr's, and leaving it
  // out is the mistake this block shipped with.
  imports: [FormField, WrCard, WrFormField, WrInput, WrButton],
})
export class SignIn {
  protected readonly model = signal({ email: '', password: '' });

  // The rules come from `@angular/forms/signals`. `WrValidators` is the other
  // half of the story and does not fit here: those are `ValidatorFn`s for a
  // reactive `FormControl`, and its set is the ones Angular has no equivalent
  // for — `cardNumber`, `iban`, `matchFields`. There is no `WrValidators.required`.
  protected readonly f = form(this.model, path => {
    required(path.email);
    email(path.email);
    required(path.password);
  });

  protected submit(): void {
    if (this.f().invalid()) return;
    // POST this.model() somewhere.
  }
}

.app-sign-in {
  display: grid;
  gap: 1rem;
  max-inline-size: 22rem;
  margin-inline: auto;
}
